//! The shared reasoning-marker vectors (`fixtures/reasoning-marker/v1.json`)
//! read by `cvc_core::reasoning::read`, the reference reader.
//!
//! The Reviewer's TypeScript port (`cvc-reviewer/src/lib/reasoningMarker.ts`)
//! is tested against the same file, so the two readers agree on every vector.
//! The file is generated by `cvc-reviewer/scripts/reasoning-marker-vectors.mjs`.
//! `reasoning.rs` is the truth: when a vector disagrees with it, the vector
//! (or the port that produced it) is wrong, and neither side is edited here to
//! match the other.

use cvc_core::models::InteractionId;
use cvc_core::reasoning::{self, ReasoningKind, ReasoningView};
use serde::Deserialize;
use std::path::Path;

#[derive(Deserialize)]
struct Vectors {
    version: u64,
    domain: String,
    vectors: Vec<Vector>,
}

#[derive(Deserialize)]
struct Vector {
    name: String,
    id: String,
    text: String,
    kind: String,
    body: String,
}

fn vectors() -> Vectors {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/reasoning-marker/v1.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("{}: {error}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

#[test]
fn the_file_is_version_1_of_the_boundary_domain() {
    let vectors = vectors();
    assert_eq!(vectors.version, 1);
    assert_eq!(vectors.domain, "cvc.reasoning-boundary/v1");
    assert!(!vectors.vectors.is_empty());
    for kind in ["provider_summary", "unverified"] {
        assert!(
            vectors.vectors.iter().any(|vector| vector.kind == kind),
            "no {kind} vector"
        );
    }
}

#[test]
fn every_vector_reads_as_reasoning_rs_reads_it() {
    let mut disagreements = Vec::new();
    for vector in vectors().vectors {
        let id: InteractionId = vector
            .id
            .parse()
            .unwrap_or_else(|error| panic!("{}: id {:?}: {error}", vector.name, vector.id));
        let view = reasoning::read(&id, &vector.text);
        let (kind, body) = match view {
            ReasoningView::Verified {
                kind: ReasoningKind::ProviderSummary,
                body,
            } => ("provider_summary", body),
            ReasoningView::Unverified(text) => ("unverified", text),
            ReasoningView::Verified { kind, body } => {
                disagreements.push(format!(
                    "{}: reasoning.rs verified a marker of kind {kind:?}, which no vector names (body {body:?})",
                    vector.name
                ));
                continue;
            }
        };
        assert_eq!(view.body(), body, "{}", vector.name);
        if kind != vector.kind || body != vector.body {
            disagreements.push(format!(
                "{}: reasoning.rs reads {kind} with body {body:?}; the vector says {} with body {:?}",
                vector.name, vector.kind, vector.body
            ));
        }
        // Unverified text is shown whole, as reasoning the agent exposed.
        if kind == "unverified" {
            assert_eq!(view.kind(), ReasoningKind::Exposed, "{}", vector.name);
            assert_eq!(body, vector.text, "{}", vector.name);
        }
    }
    assert!(
        disagreements.is_empty(),
        "{} vector(s) disagree with reasoning.rs, which is the truth:\n{}",
        disagreements.len(),
        disagreements.join("\n")
    );
}
